module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    // Split data_in into four 2-bit segments
    wire [1:0] a0 = data_in[7:6];
    wire [1:0] a1 = data_in[5:4];
    wire [1:0] a2 = data_in[3:2];
    wire [1:0] a3 = data_in[1:0];

    // Split KEY into four 2-bit segments
    wire [1:0] k0 = KEY[7:6];
    wire [1:0] k1 = KEY[5:4];
    wire [1:0] k2 = KEY[3:2];
    wire [1:0] k3 = KEY[1:0];

    // Process each segment with its key
    wire [2:0] processed0 = process_segment(a0, k0);
    wire [2:0] processed1 = process_segment(a1, k1);
    wire [2:0] processed2 = process_segment(a2, k2);
    wire [2:0] processed3 = process_segment(a3, k3);

    // Combine processed segments into 8-bit output
    assign data_out = {processed0, processed1, processed2, processed3};

    // Function to process each segment (example: key XOR + 1)
    function [2:0] process_segment;
        input [1:0] data_seg;
        input [1:0] key_seg;
        begin
            process_segment = (data_seg ^ key_seg) + 1;
        end
    endfunction

endmodule

