module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);
    reg [7:0] a;
    reg [7:0] b;
    reg [7:0] c;

    always @(posedge clk) begin
        if (rst) begin
            a <= 8'b0;
            b <= 8'b0;
            c <= 8'b0;
        end else begin
            a <= pin;  // Store input in register a
            b <= a;     // Update register b with previous value of a
            c <= b ^ a; // Compute XOR of current a and b, store in c
        end
    end

    assign sout = c; // Output register c
endmodule

